"""Emit bend2/src/{g1,g2}.bend and bend2/tests/test_{g1,g2}.bend from one template: BN254
G1 over Fq and G2 over Fq2 share every formula (short Weierstrass with a = 0; Jacobian
coordinates; dbl-2009-l, add-2007-bl, madd-2007-bl from hyperelliptic.org/EFD), so only
the field module and the element stride (16-word units) differ.
Run: uv run python bend2/gen/gen_curve.py
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

CURVE = """\
# GENERATED by bend2/gen/gen_curve.py -- do not edit by hand.
# BN254 {G} (y^2 = x^3 + b, a = 0) over {FT}. Affine {G}Aff{{x, y}} (infinity = both zero,
# bend2/FORMAT.md); Jacobian {G}{{x, y, z}} (infinity = z zero). Formulas: dbl-2009-l (2M+5S),
# add-2007-bl (11M+5S), madd-2007-bl (7M+4S). Special cases (infinity, P == Q, P == -Q) are
# resolved by a Bool match in the *.fin defs after the generic formula is computed.
import Base
import ./{FMOD}.bend as Q
import ./fr.bend as R

type {G}Aff is Data:
  {G}Aff{{+x: {FT}, +y: {FT}}}

type {G} is Data:
  {G}{{+x: {FT}, +y: {FT}, +z: {FT}}}

def {G}.infinity() -> {G}:
  {G}{{{FT}.zero(), {FT}.one(), {FT}.zero()}}

def {G}Aff.infinity() -> {G}Aff:
  {G}Aff{{{FT}.zero(), {FT}.zero()}}

def {G}Aff.is_inf(p: {G}Aff) -> U32:
  match p:
    case {G}Aff{{x, y}}:
      U32.and({FT}.is_zero(x), {FT}.is_zero(y))

def {G}.is_inf(p: {G}) -> U32:
  match p:
    case {G}{{x, y, z}}:
      {FT}.is_zero(z)

def {G}.from_affine.fin(inf: Bool, p: {G}Aff) -> {G}:
  match inf:
    case True{{}}:
      {G}.infinity()
    case False{{}}:
      match p:
        case {G}Aff{{x, y}}:
          {G}{{x, y, {FT}.one()}}

def {G}.from_affine(+p: {G}Aff) -> {G}:
  {G}.from_affine.fin(U32.is_eq({G}Aff.is_inf(p), 1), p)

def {G}.to_affine.fin(inf: Bool, p: {G}) -> {G}Aff:
  match inf:
    case True{{}}:
      {G}Aff.infinity()
    case False{{}}:
      match p:
        case {G}{{x, y, z}}:
          +zi = {FT}.inv(z)
          +zi2 = {FT}.sqr(zi)
          {G}Aff{{{FT}.mul(x, zi2), {FT}.mul(y, {FT}.mul(zi, zi2))}}

# one field inversion
def {G}.to_affine(+p: {G}) -> {G}Aff:
  {G}.to_affine.fin(U32.is_eq({G}.is_inf(p), 1), p)

def {G}.neg(p: {G}) -> {G}:
  match p:
    case {G}{{x, y, z}}:
      {G}{{x, {FT}.neg(y), z}}

# neg(0) = 0 keeps the (0, 0) infinity encoding
def {G}Aff.neg(p: {G}Aff) -> {G}Aff:
  match p:
    case {G}Aff{{x, y}}:
      {G}Aff{{x, {FT}.neg(y)}}

def {G}.eq_affine(a: {G}Aff, b: {G}Aff) -> U32:
  match a b:
    case {G}Aff{{ax, ay}} {G}Aff{{bx, by}}:
      U32.and({FT}.eq(ax, bx), {FT}.eq(ay, by))

# dbl-2009-l; z = 0 stays z3 = 0
def {G}.double(p: {G}) -> {G}:
  match p:
    case {G}{{x, y, z}}:
      +a = {FT}.sqr(x)
      +b = {FT}.sqr(y)
      +c = {FT}.sqr(b)
      +d0 = {FT}.sub({FT}.sub({FT}.sqr({FT}.add(x, b)), a), c)
      +d = {FT}.add(d0, d0)
      +e = {FT}.add({FT}.add(a, a), a)
      +f = {FT}.sqr(e)
      +x3 = {FT}.sub(f, {FT}.add(d, d))
      +c2 = {FT}.add(c, c)
      +c4 = {FT}.add(c2, c2)
      +y3 = {FT}.sub({FT}.mul(e, {FT}.sub(d, x3)), {FT}.add(c4, c4))
      +z3 = {FT}.mul({FT}.add(y, y), z)
      {G}{{x3, y3, z3}}

def {G}.add.fin(p_inf: Bool, q_inf: Bool, h_zero: Bool, r_zero: Bool, p: {G}, q: {G}, gen: {G}) -> {G}:
  match p_inf:
    case True{{}}:
      q
    case False{{}}:
      match q_inf:
        case True{{}}:
          p
        case False{{}}:
          match h_zero:
            case False{{}}:
              gen
            case True{{}}:
              match r_zero:
                case True{{}}:
                  {G}.double(p)
                case False{{}}:
                  {G}.infinity()

# add-2007-bl (Jacobian + Jacobian)
def {G}.add(p: {G}, q: {G}) -> {G}:
  match p q:
    case {G}{{x1, y1, z1}} {G}{{x2, y2, z2}}:
      +z1z1 = {FT}.sqr(z1)
      +z2z2 = {FT}.sqr(z2)
      +u1 = {FT}.mul(x1, z2z2)
      +u2 = {FT}.mul(x2, z1z1)
      +s1 = {FT}.mul({FT}.mul(y1, z2), z2z2)
      +s2 = {FT}.mul({FT}.mul(y2, z1), z1z1)
      +h = {FT}.sub(u2, u1)
      +hh = {FT}.add(h, h)
      +i = {FT}.sqr(hh)
      +j = {FT}.mul(h, i)
      +rr = {FT}.sub(s2, s1)
      +r = {FT}.add(rr, rr)
      +v = {FT}.mul(u1, i)
      +x3 = {FT}.sub({FT}.sub({FT}.sqr(r), j), {FT}.add(v, v))
      +s1j = {FT}.mul(s1, j)
      +y3 = {FT}.sub({FT}.mul(r, {FT}.sub(v, x3)), {FT}.add(s1j, s1j))
      +z3 = {FT}.mul({FT}.sub({FT}.sub({FT}.sqr({FT}.add(z1, z2)), z1z1), z2z2), h)
      {G}.add.fin(U32.is_eq({FT}.is_zero(z1), 1), U32.is_eq({FT}.is_zero(z2), 1), U32.is_eq({FT}.is_zero(h), 1), U32.is_eq({FT}.is_zero(rr), 1), {G}{{x1, y1, z1}}, {G}{{x2, y2, z2}}, {G}{{x3, y3, z3}})

def {G}.add_mixed.fin(p_inf: Bool, q_inf: Bool, h_zero: Bool, r_zero: Bool, p: {G}, q: {G}Aff, gen: {G}) -> {G}:
  match p_inf:
    case True{{}}:
      {G}.from_affine(q)
    case False{{}}:
      match q_inf:
        case True{{}}:
          p
        case False{{}}:
          match h_zero:
            case False{{}}:
              gen
            case True{{}}:
              match r_zero:
                case True{{}}:
                  {G}.double(p)
                case False{{}}:
                  {G}.infinity()

# madd-2007-bl (Jacobian + affine), the MSM hot op
def {G}.add_mixed(p: {G}, q: {G}Aff) -> {G}:
  match p q:
    case {G}{{x1, y1, z1}} {G}Aff{{x2, y2}}:
      +z1z1 = {FT}.sqr(z1)
      +u2 = {FT}.mul(x2, z1z1)
      +s2 = {FT}.mul({FT}.mul(y2, z1), z1z1)
      +h = {FT}.sub(u2, x1)
      +hh = {FT}.sqr(h)
      +hh2 = {FT}.add(hh, hh)
      +i = {FT}.add(hh2, hh2)
      +j = {FT}.mul(h, i)
      +rr = {FT}.sub(s2, y1)
      +r = {FT}.add(rr, rr)
      +v = {FT}.mul(x1, i)
      +x3 = {FT}.sub({FT}.sub({FT}.sqr(r), j), {FT}.add(v, v))
      +y1j = {FT}.mul(y1, j)
      +y3 = {FT}.sub({FT}.mul(r, {FT}.sub(v, x3)), {FT}.add(y1j, y1j))
      +z3 = {FT}.sub({FT}.sub({FT}.sqr({FT}.add(z1, h)), z1z1), hh)
      {G}.add_mixed.fin(U32.is_eq({FT}.is_zero(z1), 1), U32.is_eq({G}Aff.is_inf({G}Aff{{x2, y2}}), 1), U32.is_eq({FT}.is_zero(h), 1), U32.is_eq({FT}.is_zero(rr), 1), {G}{{x1, y1, z1}}, {G}Aff{{x2, y2}}, {G}{{x3, y3, z3}})

def {G}.mul_scalar.step(bit: Bool, d: {G}, p: {G}) -> {G}:
  match bit:
    case True{{}}:
      {G}.add(d, p)
    case False{{}}:
      d

def {G}.mul_scalar.go(i: Nat, acc: {G}, +p: {G}, +k: R.Fr) -> {G}:
  match i:
    case 0n:
      acc
    case 1n++j:
      {G}.mul_scalar.go(j, {G}.mul_scalar.step(U32.is_eq(R.Fr.bits_window(k, j, 1n), 1), {G}.double(acc), p), p, k)

# double-and-add over the 256 bits of a CANONICAL scalar k (tests / small use; MSM has its own)
def {G}.mul_scalar(+p: {G}, +k: R.Fr) -> {G}:
  {G}.mul_scalar.go(256n, {G}.infinity(), p, k)

def {G}Aff.from_array_at.s2(+x: {FT}, p: Array<U32> & {FT}) -> Array<U32> & {G}Aff:
  (a, +y) = p
  (a, {G}Aff{{x, y}})

def {G}Aff.from_array_at.s1(+u: Nat, p: Array<U32> & {FT}) -> Array<U32> & {G}Aff:
  (a, +x) = p
  {G}Aff.from_array_at.s2(x, {FLOAD}(a, (u + {FUNITS}n)))

# load the affine point whose x starts at 16-word unit u (word 16*u)
def {G}Aff.from_array_at(a: Array<U32>, +u: Nat) -> Array<U32> & {G}Aff:
  {G}Aff.from_array_at.s1(u, {FLOAD}(a, u))

# load affine point i ({PWORDS} words at {PWORDS}*i)
def {G}Aff.from_array(a: Array<U32>, i: Nat) -> Array<U32> & {G}Aff:
  {G}Aff.from_array_at(a, (i * {PUNITS}n))

# store affine point i ({PWORDS} words at {PWORDS}*i)
def {G}Aff.to_array(a: Array<U32>, +i: Nat, p: {G}Aff) -> Array<U32>:
  match p:
    case {G}Aff{{x, y}}:
      {FT}.to_array({FT}.to_array(a, (i * 2n), x), ((i * 2n) + 1n), y)

# "x_hex y_hex" (G2: "x0 x1 y0 y1"), canonical
def {G}.show_affine(p: {G}Aff) -> String:
  match p:
    case {G}Aff{{x, y}}:
      {FT}.show(x) ++ " " ++ {FT}.show(y)
"""

OPS = ["add", "add_mixed", "double", "neg", "mul_scalar", "neg_affine", "add_rev", "roundtrip"]

TEST_HEAD = """\
# GENERATED by bend2/gen/gen_curve.py -- do not edit by hand.
# Checks {G} ops against arkworks vectors: data/vectors/bend/{g}_ops.bin (run from the repo root).
# Per case ({CU} 16-word units): p q k add double_p neg_p mul_pk; k is a canonical Fr scalar.
import Base
import ../src/{g}.bend as G
import ../src/fr.bend as R
import ../src/bin_io.bend as Io

"""

TEST_TAIL = """\
def T.check(+c: Nat, arr: Array<U32>) -> Array<U32> & U32:
  T.s0(c, G.{G}Aff.from_array_at(arr, (1n + (c * {CU}n))))

# 0xFFFFFFFF when m != 0 else 0
def T.nz(+m: U32) -> U32:
  U32.sub(0, U32.shrn(U32.or(m, U32.sub(0, m)), 31n))

# first = first failure code (case << 8 | opmask), kept once set
def T.first(+c: U32, +first: U32, +m: U32) -> U32:
  U32.or(first, U32.and(U32.and(U32.not(T.nz(first)), T.nz(m)), U32.or(U32.shln(c, 8n), m)))

# fold the result of case c-1 (r), then check case c; returns fails << 16 | first
def T.loop(n: Nat, +c: Nat, +fails: U32, +first: U32, r: Array<U32> & U32) -> U32:
  match n:
    case 0n:
      (arr, +m) = r
      U32.or(U32.shln(U32.add(fails, U32.and(T.nz(m), 1)), 16n), T.first(U32.from_nat(Nat.sub(c, 1n)), first, m))
    case 1n+p:
      (arr, +m) = r
      T.loop(p, (c + 1n), U32.add(fails, U32.and(T.nz(m), 1)), T.first(U32.from_nat(Nat.sub(c, 1n)), first, m), T.check(c, arr))

def T.opname(on: Bool, name: String) -> String:
  match on:
    case True{{}}:
      name ++ " "
    case False{{}}:
      ""

def T.opnames(+m: U32) -> String:
  {OPNAMES}

def T.report(ok: Bool, +code: U32, +cnt: U32) -> String:
  match ok:
    case True{{}}:
      "PASS " ++ U32.show(cnt)
    case False{{}}:
      "FAIL " ++ U32.show(U32.shrn(U32.and(code, 65535), 8n)) ++ " " ++ T.opnames(U32.and(code, 255)) ++ "(" ++ U32.show(U32.shrn(code, 16n)) ++ " of " ++ U32.show(cnt) ++ " cases failing)"

def T.run(r: Array<U32> & U32) -> IO(Unit):
  (arr, +cnt) = r
  +code = T.loop(U32.to_nat(cnt), 0n, 0, 0, (arr, 0))
  IO.print(T.report(U32.is_eq(U32.shrn(code, 16n), 0), code, cnt))

def main() -> IO(Unit):
  do IO<Unit>:
    arr : Array<U32> <- Io.load_u32("data/vectors/bend/{g}_ops.bin", 13n, 15)
    T.run(arr[15])
"""


def gen_test(G, PU):
    g = G.lower()
    CU = 6 * PU + 1
    # unit offsets inside a case
    offs = {"p": 0, "q": PU, "k": 2 * PU, "add": 2 * PU + 1, "dbl": 3 * PU + 1, "neg": 4 * PU + 1, "mul": 5 * PU + 1}
    names = ["p", "q", "k", "add", "dbl", "neg", "mul"]
    typ = {n: "G.%sAff" % G for n in names}
    typ["k"] = "R.Fr"
    o = []
    w = o.append
    for s in range(6, -1, -1):
        prev = ", ".join("+%s: %s" % (names[j], typ[names[j]]) for j in range(s))
        w("def T.s%d(+c: Nat, %spr: Array<U32> & %s) -> Array<U32> & U32:" % (s, prev + ", " if prev else "", typ[names[s]]))
        w("  (arr, +%s) = pr" % names[s])
        if s < 6:
            nxt = names[s + 1]
            load = "R.Fr.from_array" if nxt == "k" else "G.%sAff.from_array_at" % G
            args = ", ".join(["c"] + names[: s + 1])
            w("  T.s%d(%s, %s(arr, (1n + (c * %dn) + %dn)))" % (s + 1, args, load, CU, offs[nxt]))
        else:
            w("  +pj = G.%s.from_affine(p)" % G)
            w("  +qj = G.%s.from_affine(q)" % G)
            checks = [
                "G.{G}.eq_affine(G.{G}.to_affine(G.{G}.add(pj, qj)), add)",
                "G.{G}.eq_affine(G.{G}.to_affine(G.{G}.add_mixed(pj, q)), add)",
                "G.{G}.eq_affine(G.{G}.to_affine(G.{G}.double(pj)), dbl)",
                "G.{G}.eq_affine(G.{G}.to_affine(G.{G}.neg(pj)), neg)",
                "G.{G}.eq_affine(G.{G}.to_affine(G.{G}.mul_scalar(pj, k)), mul)",
                "G.{G}.eq_affine(G.{G}Aff.neg(p), neg)",
                "G.{G}.eq_affine(G.{G}.to_affine(G.{G}.add(qj, pj)), add)",
                "G.{G}.eq_affine(G.{G}.to_affine(pj), p)",
            ]
            for i, ch in enumerate(checks):
                w("  +ok%d = %s" % (i, ch.format(G=G)))
            terms = ["U32.shln(U32.sub(1, ok%d), %dn)" % (i, i) for i in range(len(checks))]
            acc = terms[0]
            for t in terms[1:]:
                acc = "U32.or(%s, %s)" % (acc, t)
            w("  (arr, %s)" % acc)
        w("")
    opnames = " ++ ".join('T.opname(U32.is_eq(U32.and(U32.shrn(m, %dn), 1), 1), "%s")' % (i, op) for i, op in enumerate(OPS))
    return TEST_HEAD.format(G=G, g=g, CU=CU) + "\n".join(o) + "\n" + TEST_TAIL.format(G=G, g=g, CU=CU, OPNAMES=opnames)


if __name__ == "__main__":
    for G, FMOD, FT, FLOAD, FUNITS in (
        ("G1", "fq", "Q.Fq", "Q.Fq.from_array", 1),
        ("G2", "fq2", "Q.Fq2", "Q.Fq2.from_array_at", 2),
    ):
        PU = 2 * FUNITS
        src = ROOT / "bend2" / "src" / ("%s.bend" % G.lower())
        src.write_text(CURVE.format(G=G, FMOD=FMOD, FT=FT, FLOAD=FLOAD, FUNITS=FUNITS, PUNITS=PU, PWORDS=16 * PU))
        tst = ROOT / "bend2" / "tests" / ("test_%s.bend" % G.lower())
        tst.write_text(gen_test(G, PU))
        print("wrote", src, tst)
